std::float_t phi = 2.0f * std::float_t(M_PI) * u.x();
std::float_t theta = std::acos(1.0f - 2.0f * u.y());

Vector3f direction(
    r * std::cos(phi) * std::sin(theta),
    r * std::sin(phi) * std::sin(theta),
    std::cos(theta)
);
return direction;
